  def pt(x, y, z)
    Geom::Point3d.new(x.m, y.m, z.m)
  end

  def make_materials(model)
    mats = {}
    MATERIALS.each do |name, (rgb, alpha, tex, tw, th)|
      m = model.materials[name] || model.materials.add(name)
      m.color = Sketchup::Color.new(rgb[0], rgb[1], rgb[2])
      if tex
        path = File.join(TEX_DIR, tex)
        if File.exist?(path)
          m.texture = path
          m.texture.size = [tw.m, th.m] if m.texture
        else
          puts "Villa G153: texture not found (colour used instead): #{path}"
        end
      end
      m.alpha = alpha if alpha < 1.0
      mats[name] = m
    end
    mats
  end

  def make_tags(model)
    tags = {}
    TAGS.each { |t| tags[t] = model.layers[t] || model.layers.add(t) }
    tags
  end

  def add_extrusion(ents, pts, vec, mat)
    g = ents.add_group
    face = g.entities.add_face(pts.map { |p| pt(p[0], p[1], p[2]) })
    v = Geom::Vector3d.new(vec[0].m, vec[1].m, vec[2].m)
    face.reverse! if face.normal.dot(v) < 0
    face.pushpull(v.length)
    g.material = mat
    g
  end

  def add_box(ents, x0, y0, z0, x1, y1, z1, mat)
    add_extrusion(ents, [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0]], [0, 0, z1 - z0], mat)
  end

  def add_mesh(ents, flat, tris, mat, soft)
    npts = flat.size / 3
    mesh = Geom::PolygonMesh.new(npts, tris.size / 3)
    idx = Array.new(npts) { |i| mesh.add_point(pt(flat[3 * i], flat[3 * i + 1], flat[3 * i + 2])) }
    (tris.size / 3).times do |k|
      a, b, c = idx[tris[3 * k]], idx[tris[3 * k + 1]], idx[tris[3 * k + 2]]
      mesh.add_polygon(a, b, c) unless a == b || b == c || a == c
    end
    g = ents.add_group
    flags = soft ? 12 : 0     # AUTO_SOFTEN | SMOOTH_SOFT_EDGES
    g.entities.add_faces_from_mesh(mesh, flags)
    g.material = mat
    g
  end

  def build_elements(ents, data, mats, tags)
    data.each do |name, tag, parts|
      eg = ents.add_group
      eg.name = name
      eg.layer = tags[tag] if tags[tag]
      parts.each do |p|
        begin
          case p[0]
          when 'b' then add_box(eg.entities, p[2], p[3], p[4], p[5], p[6], p[7], mats[p[1]])
          when 'e' then add_extrusion(eg.entities, p[2], p[3], mats[p[1]])
          when 'm' then add_mesh(eg.entities, p[2], p[3], mats[p[1]], p[4])
          end
        rescue StandardError => e
          puts "Villa G153: skipped one primitive in '#{name}' (#{e.message})"
        end
      end
    end
  end

  def build_street(ents, mats, tags, houses)
    len = houses * PLOT_WIDTH
    data = [
      ['Street - Road', '12 Site', [['b', 'Asphalt', -15, -11.05, -0.30, len + 15, -2.55, -0.15]] +
        (0...((len + 28) / 6.0).floor).map { |i| x = -14 + 6 * i; ['b', 'Road_Marking', x, -6.86, -0.15, x + 3, -6.74, -0.148] }],
      ['Street - Opposite Sidewalk & Hedge', '12 Site', [
        ['b', 'Curb', -15, -11.20, -0.25, len + 15, -11.05, 0],
        ['b', 'Sidewalk', -15, -13.60, -0.20, len + 15, -11.20, 0],
        ['b', 'Foliage', -15, -14.60, 0, len + 15, -13.60, 1.20]]],
      ['Street - End Ground', '12 Site', [
        ['b', 'Grass', -15, -2.55, -0.20, 0, 22, 0],
        ['b', 'Grass', len, -2.55, -0.20, len + 15, 22, 0]]],
    ]
    sg = ents.add_group
    sg.name = 'Gated Street'
    build_elements(sg.entities, data, mats, tags)
    sg
  end

  def add_scene(model, name, eye, target, perspective, fov_or_height)
    cam = Sketchup::Camera.new(pt(*eye), pt(*target), Geom::Vector3d.new(0, 0, 1))
    if perspective
      cam.perspective = true
      cam.fov = fov_or_height
    else
      cam.perspective = false
      cam.height = fov_or_height.m
    end
    model.active_view.camera = cam
    page = model.pages.add(name)
    page.use_camera = true
    page.use_shadow_info = true
    page
  end

  def setup_model(model)
    units = model.options['UnitsOptions']
    units['LengthUnit'] = 4        # metres
    units['LengthFormat'] = 0      # decimal
    units['LengthPrecision'] = 2
    si = model.shadow_info
    si['Latitude'] = 30.51
    si['Longitude'] = 47.81
    si['TZOffset'] = 3.0
    si['ShadowTime'] = Time.utc(2026, 10, 15, 15, 30)   # read by SketchUp as local solar time
    si['Light'] = 85
    si['Dark'] = 42
    si['UseSunForAllShading'] = true
    si['DisplayShadows'] = true
  end

  def build
    model = Sketchup.active_model
    t0 = Time.now
    model.start_operation('Build Villa G153 elevation', true)
    begin
      setup_model(model)
      mats = make_materials(model)
      tags = make_tags(model)
      defn = model.definitions.add(DEF_NAME)
      defn.description = 'Villa Type G153 (Farah City, Basra) - typical house with designed front elevation. ' \
                         'Plot 12.50 x 20.00 m. Edit once, all plots update.'
      build_elements(defn.entities, HOUSE, mats, tags)
      n = [HOUSES_IN_STREET.to_i, 1].max
      n.times do |i|
        inst = model.entities.add_instance(defn, Geom::Transformation.translation(Geom::Vector3d.new((i * PLOT_WIDTH).m, 0, 0)))
        inst.name = format('Plot %02d', i + 1)
      end
      build_street(model.entities, mats, tags, n) if BUILD_STREET
      hx = (n / 2) * PLOT_WIDTH      # hero house = middle plot
      add_scene(model, '01 Front Elevation',   [hx + 6.25, -45, 5.2], [hx + 6.25, 0, 5.2], false, 12.8)
      add_scene(model, '02 Street Perspective', [hx - 3.6, -13.5, 1.65], [hx + 5.6, 3.2, 4.6], true, 50)
      add_scene(model, '03 Entrance Close-up', [hx + 2.2, -5.0, 1.6], [hx + 5.2, 3.0, 3.4], true, 62)
      add_scene(model, '04 Gated Street',      [-4.0, -10.5, 1.7], [22.0, 6.0, 4.4], true, 50)
      add_scene(model, '05 Aerial',            [-14, -30, 24], [16, 7, 3], true, 42)
      model.pages.selected_page = model.pages[1]
      model.commit_operation
      msg = "Villa G153 built: #{n} house(s) in #{(Time.now - t0).round(1)} s. Save it with File > Save As (.skp)."
      puts msg
      Sketchup.status_text = msg
    rescue StandardError => e
      model.abort_operation
      puts "Villa G153 builder error: #{e.message}\n#{e.backtrace.first(5).join("\n")}"
      UI.messagebox("Villa G153 builder error:\n#{e.message}")
    end
  end
end

VillaG153Builder.build
